const app = document.querySelector('#app');
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
const SERVICES = [
{title:'dinners',intro:'intimate, intentional, and built around conversation. for founders, customers, investors, or your own team.',details:['12–60 seats','venue sourcing, menu, seating plan, invites, day-of hosting','place cards, printed menus, and a photographer'],timeline:'2–3 weeks'},
{title:'company events',intro:'nights your team actually wants to come to. holiday parties, offsites, milestone celebrations, team nights.',details:['30–200 people','venue, catering, bar, entertainment, décor, run-of-show','optional: programming, awards, speakers, merch'],timeline:'3–6 weeks'},
{title:'launch parties',intro:'the night the internet hears about it. product drops, fundraise announcements, office openings.',details:['75–300 people','concept + theme, venue, production, guest list strategy, press and creator invites','content capture built in, so the night lives online after it ends'],timeline:'3–6 weeks'},
{title:'brand activations & pop-ups',intro:'physical experiences people line up for and post about.',details:['concept, spatial design, fabrication, permits, staffing, and on-site management','one-night takeovers to multi-day pop-ups','designed for foot traffic, content, and measurable results'],timeline:'6–10 weeks'}
];
const PROCESS = [
['brief','day 1','a 30-minute call. we learn the goal, the audience, the budget, and the date.'],
['concept','within 5 business days','you get a full plan: theme, 2–3 venue options, guest profile, run-of-show, and an itemized budget. we revise until it’s right.'],
['build','weeks before','we book the venue and vendors, design everything guests will see, send invites, and manage rsvps. we help shape the guest list around your goals, and you have the final say. one point of contact, weekly updates.'],
['the night','event day','we run setup, vendors, the door, and the timeline. you just show up and work the room.'],
['recap','within 1 week','photos, attendee list, final budget reconciliation, and a short debrief on what worked and what we’d do next time.']
];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(p,i=0){return `<a class="project-card" href="/work/${p.slug}" aria-label="View ${p.title}">${p.slug==='moon-copy'?'<span class="new-tag">NEW</span>':''}<div class="card-image"><img src="${p.images[0]}" alt="${p.title}" ${i<5?'fetchpriority="high"':'loading="lazy"'}>${p.videos.length?`<video src="${p.videos[0]}" poster="${p.images[0]}" muted loop playsinline preload="none" aria-hidden="true"></video>`:''}</div><span class="card-caption">${p.title}</span></a>`}
function strip(){return `<div class="project-strip">${PROJECTS.slice(0,5).map(card).join('')}</div>`}
function footer(){return `<footer>${strip()}<div class="footer"><div class="footer-columns"><div><a href="/">Home</a><a href="/work/works">Work</a><a href="/services">Services</a><a href="/about">About</a></div><div><p>contact</p><p>details coming soon</p></div><div><p>studio location coming soon</p></div></div><div class="footer-bottom"><span>curfew studios</span><span>© All Rights Reserved</span></div></div></footer>`}
function home(){app.className='home';app.innerHTML=`<section class="hero" aria-label="curfew studios"><div class="hero-content"><h1>worth breaking curfew for.</h1><p>launches, dinners, and brand activations for startups. you set the budget, we make it happen.</p></div></section><section class="home-projects" aria-label="selected projects">${PROJECTS.slice(0,5).map(card).join('')}</section>`;}
function works(){app.className='work-page';app.innerHTML=`<h1 class="sr-only">Selected work</h1><div class="work-grid">${PROJECTS.map(card).join('')}</div><aside class="work-list" id="work-list" aria-label="Project list" hidden>${PROJECTS.map(p=>`<a href="/work/${p.slug}" data-preview="${p.images[0]}">${p.title}</a>`).join('')}</aside><button class="list-toggle" aria-expanded="false" aria-controls="work-list">List</button>`;const btn=document.querySelector('.list-toggle');btn.onclick=()=>{const open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',open);btn.textContent=open?'close':'list';document.querySelector('.work-list').hidden=!open;document.querySelector('.work-grid').classList.toggle('dimmed',open)};
if(matchMedia('(hover:hover)').matches&&!reduced)document.querySelectorAll('.work-grid .project-card').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.querySelector('.card-image').style.transform=`translate(${(e.clientX-r.left-r.width/2)*.055}px,${(e.clientY-r.top-r.height/2)*.055}px)`});el.addEventListener('pointerleave',()=>el.querySelector('.card-image').style.transform='')})}
function services(){app.className='page';app.innerHTML=`<div class="editorial services"><h1 class="sr-only">Offerings</h1>${SERVICES.map(o=>`<section class="editorial-row"><h2 class="eyebrow">${o.title}</h2><div><p class="editorial-copy">${o.intro}</p><ul class="offering-details">${o.details.map(d=>`<li>${d}</li>`).join('')}</ul><p class="offering-meta">typical timeline: ${o.timeline}</p><div class="service-projects">${PROJECTS.filter(p=>p.services.includes(o.title)).map(card).join('')}</div></div></section>`).join('')}<section class="editorial-row"><h2 class="eyebrow">process</h2><ol class="process-steps">${PROCESS.map(([step,when,desc],i)=>`<li><h3 class="editorial-copy">${step}</h3><p class="offering-meta">${String(i+1).padStart(2,'0')} · ${when}</p><p class="offering-body">${desc}</p></li>`).join('')}</ol></section><section class="editorial-row"><h2 class="eyebrow">pricing, simply</h2><p class="editorial-copy">all costs passed through at cost with receipts, plus a clear management fee. dinners are a flat fee, larger events are a percentage of spend. you’ll see every number before anything is booked.</p></section></div>${footer()}`}
function about(){app.className='page';app.innerHTML=`<button class="showreel" aria-label="Play studio showreel"><span class="new-tag">SHOWREEL</span><span class="showreel-placeholder" aria-hidden="true"></span></button><div class="editorial about"><h1 class="editorial-copy about-intro">we’re curfew studios, a creative studio making digital things for brands, people, and good ideas. We mix strategy, design, and technology to turn ideas into thoughtful experiences that look great, feel right, and make people want to stick around.</h1><section class="editorial-row"><h2 class="eyebrow">Approach</h2><p class="editorial-copy">Good work starts with a good idea. We keep things simple, ask the right questions, and care about every little detail. From the first sketch to the final pixel, we create with purpose, curiosity, and a healthy dislike for boring.</p></section><section class="editorial-row"><h2 class="eyebrow">Philosophy</h2><p class="editorial-copy">Make it simple, make it useful, and make it worth remembering. We believe good design doesn’t need to shout to get noticed—it just needs the right idea, a little personality, and a lot of care.</p></section><section class="editorial-row"><h2 class="eyebrow">Services</h2><div class="editorial-copy">${SERVICES.map(s=>`<a href="/services">${s.title}</a>`).join('')}</div></section></div>${footer()}<dialog class="reel-dialog"><button class="close-reel" aria-label="Close showreel">×</button><div class="reel-placeholder" role="img" aria-label="gray showreel placeholder"><span>showreel coming soon</span></div></dialog>`;const dialog=document.querySelector('dialog');document.querySelector('.showreel').onclick=()=>{dialog.showModal()};const close=()=>{dialog.close()};document.querySelector('.close-reel').onclick=close;dialog.addEventListener('click',e=>{if(e.target===dialog)close()})}
function detail(p){const idx=PROJECTS.indexOf(p);document.title=`${p.title} — curfew studios`;app.className='project-page';app.innerHTML=`<div class="project-backdrop" style="background-image:url('${p.images[0]}')"></div><section class="project-gallery" tabindex="0" aria-label="${p.title} image gallery"><article class="project-info"><div><h1>${p.title}</h1><p>${escapeHtml(p.intro)}</p></div><dl><div><dt>Date</dt><dd>${p.date}</dd></div><div><dt>Client</dt><dd>${p.client}</dd></div><div><dt>Services</dt><dd>${p.services.join('<br>')}</dd></div><div><dt>Description</dt><dd>${escapeHtml(p.description)}</dd></div></dl></article>${p.images.map((src,i)=>`<figure><img src="${src}" alt="${p.title} — image ${i+1}" ${i>2?'loading="lazy"':''}>${i===0&&p.videos.length?`<video src="${p.videos[0]}" poster="${src}" autoplay muted loop playsinline aria-hidden="true"></video>`:''}</figure>`).join('')}</section><nav class="project-pagination" aria-label="Project navigation"><a href="/work/${PROJECTS[(idx+PROJECTS.length-1)%PROJECTS.length].slug}">Prev</a><a href="/work/${PROJECTS[(idx+1)%PROJECTS.length].slug}">Next</a></nav>`;const gallery=document.querySelector('.project-gallery');gallery.addEventListener('wheel',e=>{if(innerWidth<810||Math.abs(e.deltaX)>Math.abs(e.deltaY))return;const can=(e.deltaY>0&&gallery.scrollLeft<gallery.scrollWidth-gallery.clientWidth-1)||(e.deltaY<0&&gallery.scrollLeft>0);if(can){e.preventDefault();gallery.scrollLeft+=e.deltaY}},{passive:false});gallery.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();gallery.scrollBy({left:(e.key==='ArrowRight'?1:-1)*360,behavior:reduced?'instant':'smooth'})}})}
const path=location.pathname.replace(/\/$/,'')||'/';if(path==='/')home();else if(path==='/work/works')works();else if(path==='/services')services();else if(path==='/about')about();else {const project=PROJECTS.find(p=>path===`/work/${p.slug}`);if(project)detail(project);else {app.className='not-found';app.innerHTML='<h1>Page not found</h1><a href="/">Back to home</a>'}}
// The compact navigation responds to pointer, touch, and keyboard.
const nav=document.querySelector('#nav'),brand=nav.querySelector('.brand'),navBody=nav.querySelector('.nav-body');
function menu(open){nav.classList.toggle('open',open);brand.setAttribute('aria-expanded',String(open));navBody.inert=!open}menu(false);
brand.addEventListener('click',()=>menu(!nav.classList.contains('open')));let closeTimer;nav.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){clearTimeout(closeTimer);menu(true)}});nav.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')closeTimer=setTimeout(()=>menu(false),300)});nav.addEventListener('focusout',e=>{if(!nav.contains(e.relatedTarget))menu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu(false);brand.focus();const toggle=document.querySelector('.list-toggle[aria-expanded="true"]');toggle?.click()}});document.addEventListener('pointerdown',e=>{if(!nav.contains(e.target))menu(false)});
// Pause offscreen films and respect reduced-motion preferences.
const videos=document.querySelectorAll('.card-image video');if(!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting)target.play().catch(()=>{});else target.pause()}),{threshold:.2});videos.forEach(v=>observer.observe(v))}else document.querySelectorAll('video').forEach(v=>{v.autoplay=false;v.pause()});
// Shared images flow between the portfolio and project pages in supporting browsers.
if(!reduced){document.querySelectorAll('.project-card').forEach(el=>{const slug=el.getAttribute('href').split('/').pop();el.addEventListener('click',()=>{document.querySelectorAll('[style*="view-transition-name"]').forEach(other=>other.style.viewTransitionName='none');el.querySelector('.card-image').style.viewTransitionName=`project-${slug}`})});const firstImage=document.querySelector('.project-gallery figure');if(firstImage)firstImage.style.viewTransitionName=`project-${path.split('/').pop()}`}

const lowercaseText = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while(lowercaseText.nextNode()){const node=lowercaseText.currentNode;if(!['SCRIPT','STYLE'].includes(node.parentElement.tagName))node.nodeValue=node.nodeValue.toLowerCase();}
document.querySelectorAll('[aria-label]').forEach(el=>el.setAttribute('aria-label',el.getAttribute('aria-label').toLowerCase()));
document.title=document.title.toLowerCase();
